import sys

def find_nth_element(n):
    if n <= 3:
        return n
    k = (n - 3) // 3
    r = (n - 3) % 3
    if r == 0:
        return 4 * (k + 1)
    elif r == 1:
        return 4 * (k + 1) + 2 * (k + 1)
    else:
        return 4 * (k + 1) + 3 * (k + 1)

def main():
    import sys
    input = sys.stdin.read().split()
    t = int(input[0])
    results = []
    for i in range(1, t + 1):
        n = int(input[i])
        results.append(find_nth_element(n))
    print(' '.join(map(str, results)))

main()
